&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Vol tarief (vanaf juni)&lt;/p&gt;&lt;/td&gt;
