&lt;li&gt;&lt;a href=&quot;#_erfgoed_supabase&quot;&gt;Erfgoed Supabase&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_dubbele_spookinzending&quot;&gt;Dubbele spookinzending&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_waarom_firebase_in_plaats_van_supabase&quot;&gt;Waarom Firebase in plaats van Supabase?&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_fase_1_maak_het_firebase_project&quot;&gt;Fase 1: Maak het Firebase-project&lt;/a&gt;
