&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;strong&gt;Bijlagen A+B&lt;/strong&gt;&lt;/p&gt;&lt;/td&gt;
