&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;metrisch&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;Voor&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;Na&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Regels van code&lt;/p&gt;&lt;/td&gt;
