&lt;li&gt;&lt;a href=&quot;#_varianten_maken&quot;&gt;Varianten maken&lt;/a&gt;
&lt;ul class=&quot;sectlevel3&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_gekleurde_cirkel&quot;&gt;gekleurde cirkel&lt;/a&gt;&lt;/li&gt;
