&lt;li&gt;&lt;a href=&quot;#_de_diagnose_4&quot;&gt;De diagnose&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_de_oplossing_4&quot;&gt;De oplossing&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
